  "尚未查到原生成任务，请稍后再次查询。不会自动重复生成。": {
    "en": "The original generation task hasn't been found yet. Check again later. It won't be generated again automatically.",
    "ms": "Tugasan penjanaan asal belum ditemui. Semak semula nanti. Penjanaan tidak akan diulang secara automatik."
  },
  "尚未确认重新推荐，当前仍为原方案，请核对后手动重新推荐。": {
    "en": "You haven't confirmed a new recommendation. The original plan is still in place. Check it and request a new recommendation manually.",
    "ms": "Anda belum mengesahkan cadangan baharu. Pelan asal masih digunakan. Semak dan minta cadangan baharu secara manual."
  },
  "尚未填写内容": {
    "en": "No content entered",
    "ms": "Tiada kandungan dimasukkan"
  },
  "设备与加工细节做主图，用精简文字展示工艺。": {
    "en": "Feature equipment and processing details in the main image, with concise text explaining the process.",
    "ms": "Tonjolkan peralatan dan butiran pemprosesan dalam imej utama, dengan teks ringkas yang menerangkan proses."
  },
  "设计3:4竖版工厂宣传海报。深海军蓝、金属灰与米白，少量安全橙强调。真实设备、加工或样件照片约占70%，以精简文字配合主图；标题清晰醒目，{value0}条要点有序排列，多张原图可选一张作主图、其余作小幅细节图。风格专业简洁，不做科幻界面。": {
    "en": "Design a 3:4 portrait factory promotional poster. Use deep navy, metallic grey and off-white, with small accents of safety orange. Real photos of equipment, processing or sample parts should take up about 70% of the space, paired with concise text and a main image. Make the title clear and prominent, arrange {value0} key points in order, and use one original photo as the main image and the rest as smaller detail images if there are multiple. Keep the style professional and simple, not sci-fi.",
    "ms": "Reka poster promosi kilang menegak 3:4. Gunakan warna biru laut gelap, kelabu metalik dan putih pudar, dengan sedikit aksen jingga keselamatan. Foto sebenar peralatan, pemprosesan atau sampel hendaklah memenuhi kira-kira 70% ruang, digandingkan dengan teks ringkas dan imej utama. Pastikan tajuk jelas dan menonjol, susun {value0} perkara utama dengan teratur. Jika terdapat beberapa foto asal, pilih satu sebagai imej utama dan gunakan yang lain sebagai imej perincian yang lebih kecil. Kekalkan gaya profesional dan ringkas, bukan gaya fiksyen sains."
  },
  "设计3:4竖版小红书推销笔记封面。米白纸张底、深黑中文粗体、番茄红重点与少量奶油黄划线。文字约占70%，工艺照片合计约20%，余下留白；顶部超大标题，信息区分为{value0}块编号便签，按条数灵活排版，每条中的“｜”分隔短标题和解释。小照片带细边框，少量手绘圈线和箭头，手机上清晰易读。不要蓝色企业画册风。": {
    "en": "Design a 3:4 portrait Xiaohongshu promotional post cover. Use an off-white paper background, bold black Chinese text, tomato-red highlights and a few cream-yellow underlines. Text should take up about 70% of the space, process photos about 20%, with the rest left blank. Put an oversized title at the top and divide the information into {value0} numbered note blocks, adjusting the layout to fit the number of points. In each point, use “｜” to separate the short heading from its explanation. Give small photos thin borders, add a few hand-drawn circles and arrows, and make everything easy to read on a phone. Avoid a blue corporate brochure style.",
    "ms": "Reka kulit siaran promosi Xiaohongshu dalam format menegak 3:4. Gunakan latar kertas putih pudar, teks Cina tebal berwarna hitam, sorotan merah tomato dan sedikit garisan bawah kuning krim. Teks hendaklah memenuhi kira-kira 70% ruang, foto proses kira-kira 20%, dan selebihnya dibiarkan kosong. Letakkan tajuk yang sangat besar di bahagian atas dan bahagikan maklumat kepada {value0} blok nota bernombor; laraskan susun atur mengikut bilangan perkara. Dalam setiap perkara, gunakan “｜” untuk memisahkan tajuk pendek daripada penerangannya. Letakkan bingkai nipis pada foto kecil, tambah beberapa bulatan dan anak panah gaya lukisan tangan, dan pastikan semuanya mudah dibaca pada telefon. Elakkan gaya brosur korporat berwarna biru."
  },
