  "深蓝工业色、金属加工主画面与检验辅图，把加工过程讲清楚。": {
    "en": "Use industrial deep blue, a metalworking main image and supporting inspection photos to clearly explain the process.",
    "ms": "Gunakan warna biru industri gelap, imej utama kerja logam dan foto pemeriksaan sokongan untuk menerangkan proses dengan jelas."
  },
  "深色机器与切割光点形成对比，突出加工过程的视觉节奏。": {
    "en": "Contrast dark machinery with sparks of cutting light to highlight the visual rhythm of the process.",
    "ms": "Bezakan jentera gelap dengan percikan cahaya pemotongan untuk menonjolkan rentak visual proses."
  },
