  "使用瑜伽工作室实拍制作一张课程介绍海报，风格安静自然，浅色背景，留出课程名称和预约信息。不添加未经确认的功效承诺。": {
    "en": "Use real photos of a yoga studio to create a course introduction poster. Keep the style calm and natural, with a light-coloured background and space for the course name and booking information. Do not add unverified claims about benefits.",
    "ms": "Gunakan foto sebenar studio yoga untuk menghasilkan poster pengenalan kelas. Kekalkan gaya yang tenang dan semula jadi, dengan latar berwarna cerah serta ruang untuk nama kelas dan maklumat tempahan. Jangan tambah dakwaan manfaat yang belum disahkan."
  },
