  "围绕材料、工艺与规格帮助客户判断能否加工。": {
    "en": "Help customers assess whether a product can be manufactured based on its materials, craftsmanship, and specifications.",
    "ms": "Bantu pelanggan menilai sama ada produk boleh dihasilkan berdasarkan bahan, cara pembuatan dan spesifikasinya."
  },
  "围绕可确认的一款或一组主推产品，展示整体、局部与体验理由。环境作背景；口味、原料和工艺需要文字资料支持。": {
    "en": "Focus on one confirmed featured product or set. Show the overall product, its details, and reasons to try it. Use the setting as a backdrop; claims about taste, ingredients, and craftsmanship must be supported by written information.",
    "ms": "Fokus pada satu produk atau set utama yang telah disahkan. Paparkan keseluruhan produk, butiran dan sebab untuk mencubanya. Jadikan suasana sebagai latar; maklumat tentang rasa, ramuan dan cara pembuatan perlu disokong oleh bahan bertulis."
  },
  "围绕上传原图制作图组，保留产品结构、材质、标识与真实场地，不生成不存在的店面或设备。": {
    "en": "Create an image set based on the uploaded original. Preserve the product’s structure, material, markings, and actual location; do not generate shops or equipment that do not exist.",
    "ms": "Hasilkan set imej berdasarkan imej asal yang dimuat naik. Kekalkan struktur, bahan, tanda dan lokasi sebenar produk; jangan jana kedai atau peralatan yang tidak wujud."
  },
  "围绕填写的特点选择材料、产品或服务细节。": {
    "en": "Choose details about materials, products, or services based on the features provided.",
    "ms": "Pilih butiran bahan, produk atau perkhidmatan berdasarkan ciri-ciri yang diberikan."
  },
  "围绕同一主题，生成不同视觉风格，方便比较和挑选。": {
    "en": "Generate different visual styles around the same theme for easy comparison and selection.",
    "ms": "Jana pelbagai gaya visual dengan tema yang sama untuk memudahkan perbandingan dan pemilihan."
  },
  "围绕同一主题，生成色彩与排版统一的一组图片。": {
    "en": "Generate a set of images around the same theme with consistent colours and layout.",
    "ms": "Jana satu set imej dengan tema, warna dan susun atur yang seragam."
  },
  "围绕真实套餐内容、价格、使用条件和期限编排。未提供必要事实时先追问，不能编造优惠与活动。": {
    "en": "Build the content around the actual package details, price, terms of use, and validity period. Ask for clarification if essential facts are missing; do not make up discounts or promotions.",
    "ms": "Susun kandungan berdasarkan butiran pakej, harga, syarat penggunaan dan tempoh sah yang sebenar. Minta penjelasan jika maklumat penting tiada; jangan reka diskaun atau promosi."
  },
