  "我上传的": {
    "en": "Uploaded by me",
    "ms": "Dimuat naik oleh saya"
  },
  "我想介绍工厂的生产加工业务。请帮我梳理加工范围、目标采购商、材料或工艺、规格、起订量、打样和交期。让采购商知道询价时要提供什么，不编造产能、资质或客户案例。": {
    "en": "I want to introduce my factory’s manufacturing and processing services. Please help me outline the processing scope, target buyers, materials or processes, specifications, minimum order quantity, sampling, and lead time. Let buyers know what information to provide when requesting a quote. Do not make up production capacity, qualifications, or customer case studies.",
    "ms": "Saya ingin memperkenalkan perkhidmatan pembuatan dan pemprosesan kilang. Bantu saya menyusun skop pemprosesan, sasaran pembeli, bahan atau proses, spesifikasi, kuantiti pesanan minimum, pengambilan sampel dan tempoh penghantaran. Maklumkan kepada pembeli maklumat yang perlu diberikan semasa meminta sebut harga. Jangan mereka-reka kapasiti pengeluaran, kelayakan atau kisah kejayaan pelanggan."
  },
  "我想宣传零售门店。请按顾客的使用场景整理产品选择、材质或规格、实拍细节和到店路线。请先确认价格与适用条件，不编造销量和优惠。": {
    "en": "I want to promote a retail shop. Organise the product options, materials or specifications, real-life details, and directions to the shop around customers’ use cases. Confirm the prices and conditions first. Do not make up sales figures or discounts.",
    "ms": "Saya ingin mempromosikan kedai runcit. Susun pilihan produk, bahan atau spesifikasi, perincian sebenar dan arah ke kedai mengikut situasi penggunaan pelanggan. Sahkan harga dan syarat terlebih dahulu. Jangan mereka-reka angka jualan atau diskaun."
  },
  "我想宣传门店的餐饮活动。先区分套餐、代金券或单品优惠，再核对价格、包含内容、适用人数、时间和限制，整理成顾客能看懂的图文。没有提供的事实先留待确认。": {
    "en": "I want to promote a dining offer at my shop. First distinguish between set meals, vouchers, and discounts on individual items. Then verify the price, what’s included, number of eligible diners, dates, and restrictions, and present the details in clear images and text. Leave any unprovided facts for confirmation.",
    "ms": "Saya ingin mempromosikan tawaran makanan di kedai. Mula-mula, bezakan antara set hidangan, baucar dan diskaun untuk item tertentu. Kemudian, semak harga, perkara yang termasuk, bilangan pelanggan yang layak, tempoh dan sekatan. Susun maklumat dalam bentuk imej dan teks yang mudah difahami. Tandakan fakta yang belum diberikan untuk pengesahan."
  },
  "我想用真实案例介绍美业服务。请整理顾客诉求、服务项目、过程和适合人群，提醒我补充已获授权的实拍图，不夸大效果，也不伪造前后对比。": {
    "en": "I want to showcase beauty services through real customer stories. Organise the customer’s needs, services, process, and suitable audience. Remind me to add real photos with permission. Do not exaggerate results or fabricate before-and-after comparisons.",
    "ms": "Saya ingin memperkenalkan perkhidmatan kecantikan melalui kisah pelanggan sebenar. Susun maklumat tentang keperluan pelanggan, perkhidmatan, proses dan golongan yang sesuai. Ingatkan saya untuk menambah foto sebenar yang telah mendapat kebenaran. Jangan melebih-lebihkan hasil atau mereka-reka perbandingan sebelum dan selepas."
  },
  "我已核对预览和上述提示，确认可以使用这些照片和内容。": {
    "en": "I have checked the preview and the notices above, and confirm that these photos and content can be used.",
    "ms": "Saya telah menyemak pratonton dan makluman di atas, serta mengesahkan bahawa foto dan kandungan ini boleh digunakan."
  },
  "我拥有这些照片的使用权，并已获得照片中人物的使用授权。": {
    "en": "I have the right to use these photos and have obtained permission from the people pictured.",
    "ms": "Saya mempunyai hak untuk menggunakan foto ini dan telah mendapat kebenaran daripada individu yang terdapat di dalamnya."
  },
