  "参考素材 {value0}/{value1}": {
    "en": "Reference material {value0}/{value1}",
    "ms": "Bahan rujukan {value0}/{value1}"
  },
  "参考素材行业": {
    "en": "Reference material industry",
    "ms": "Industri bahan rujukan"
  },
  "参考陶瓷货品的成组陈列，用我的实际产品照片按款式与规格整理供货图。保留真实釉色、形状和数量条件，起批、混批、运费和库存均以已确认信息为准。": {
    "en": "Use grouped displays of ceramic products as a reference. Organise supply images by style and specifications using my actual product photos. Keep the real glaze colours, shapes and quantity terms. Base minimum order quantities, mixed batches, shipping fees and stock on confirmed information only.",
    "ms": "Jadikan paparan berkumpulan produk seramik sebagai rujukan. Susun gambar produk untuk pembekalan mengikut gaya dan spesifikasi menggunakan foto produk sebenar saya. Kekalkan warna glasir, bentuk dan syarat kuantiti yang sebenar. Nyatakan kuantiti pesanan minimum, pesanan campuran, caj penghantaran dan stok berdasarkan maklumat yang telah disahkan sahaja."
  },
  "参考图片": {
    "en": "Reference image",
    "ms": "Gambar rujukan"
  },
  "参考图片已不在当前页面，请重新选择图片，或仅用文字继续。": {
    "en": "The reference image is no longer on this page. Please select it again or continue with text only.",
    "ms": "Gambar rujukan tiada lagi pada halaman ini. Sila pilih semula atau teruskan dengan teks sahaja."
  },
  "参考自然光和空间层次，使用我的实际训练场地、器械和课程素材制作介绍。保持场地真实，不夸大空间、不增加不存在的设备，不承诺减重或治疗效果。": {
    "en": "Use natural lighting and spatial depth as a reference. Use my actual training space, equipment and course materials to create an introduction. Keep the space authentic. Do not exaggerate its size, add equipment that isn't there, or promise weight loss or treatment results.",
    "ms": "Jadikan pencahayaan semula jadi dan kedalaman ruang sebagai rujukan. Gunakan ruang latihan, peralatan dan bahan kursus sebenar saya untuk menghasilkan pengenalan. Pastikan ruang dipaparkan dengan tepat. Jangan membesar-besarkan saiznya, menambah peralatan yang tiada atau menjanjikan hasil penurunan berat badan atau rawatan."
  },
