  "给采购方足够的信息，带着明确需求来咨询。": {
    "en": "Give buyers enough information so they can enquire with clear requirements.",
    "ms": "Berikan maklumat yang mencukupi kepada pembeli supaya mereka boleh bertanya dengan keperluan yang jelas."
  },
  "给角色起个名字": {
    "en": "Name the character",
    "ms": "Namakan watak"
  },
  "给提示词起个名字": {
    "en": "Name the prompt",
    "ms": "Namakan arahan"
  },
  "根据餐厅实拍做一条面向附近居民的宣传视频，展示就餐环境和招牌菜。只有我提供了套餐价格、内容和有效期时，才展示团购信息。": {
    "en": "Create a promotional video for nearby residents using actual footage of the restaurant, showcasing the dining area and signature dishes. Only include group-buying offers if I provide the package price, details and validity period.",
    "ms": "Hasilkan video promosi untuk penduduk berhampiran menggunakan rakaman sebenar restoran, dengan memaparkan ruang makan dan hidangan istimewa. Paparkan tawaran pembelian berkumpulan hanya jika saya memberikan harga pakej, butiran dan tempoh sah."
  },
  "根据上传素材安排竖屏镜头，不补造未提供的生产、服务或成交场景。": {
    "en": "Plan vertical shots based on the uploaded materials. Do not invent production, service or sales scenarios that were not provided.",
    "ms": "Rancang syot menegak berdasarkan bahan yang dimuat naik. Jangan mereka-reka situasi pengeluaran, perkhidmatan atau jualan yang tidak diberikan."
  },
  "根据实拍编排同城团购视频，缺少套餐资料时先告诉我需要补充什么。": {
    "en": "Create a local group-buying video from actual footage. If package details are missing, tell me what needs to be added first.",
    "ms": "Hasilkan video pembelian berkumpulan setempat berdasarkan rakaman sebenar. Jika butiran pakej tiada, beritahu saya perkara yang perlu ditambah terlebih dahulu."
  },
  "根据实拍编排一次连贯的到店体验，展现选择、体验与细节，没有实拍支持的服务环节不可编造。": {
    "en": "Use actual footage to create a coherent in-store experience, showing the choices, experience and details. Do not invent service steps that are not supported by the footage.",
    "ms": "Gunakan rakaman sebenar untuk menggambarkan pengalaman di premis yang lancar, termasuk pilihan, pengalaman dan butiran. Jangan mereka-reka langkah perkhidmatan yang tidak disokong oleh rakaman."
  },
  "根据我的家具成品原图制作工厂直销选购图，保留真实款式、颜色、尺寸比例和材质。依次展示全貌、局部做工和选购依据，再说明我提供的定制范围、看样与交付条件，不编造厂价、库存或包安装承诺。": {
    "en": "Create a factory-direct shopping image using my original photos of finished furniture. Keep the actual design, colour, proportions and materials. Show the full piece, craftsmanship details and reasons to buy in sequence, then describe the customisation options, viewing arrangements and delivery terms I provide. Do not invent factory prices, stock availability or promises of included installation.",
    "ms": "Hasilkan imej untuk pembelian terus dari kilang menggunakan foto asal perabot siap saya. Kekalkan reka bentuk, warna, nisbah saiz dan bahan yang sebenar. Paparkan keseluruhan produk, perincian kemasan dan sebab untuk membelinya mengikut turutan, kemudian terangkan pilihan penyesuaian, aturan melihat sampel dan syarat penghantaran yang saya berikan. Jangan mereka-reka harga kilang, ketersediaan stok atau janji pemasangan percuma."
  },
  "根据已填写的商家信息整理。请核对内容；替换前也可返回保存当前草稿。": {
    "en": "Compiled from the business information provided. Please review the content; you can also return and save the current draft before replacing it.",
    "ms": "Disusun berdasarkan maklumat perniagaan yang telah diisi. Sila semak kandungannya; anda juga boleh kembali dan menyimpan draf semasa sebelum menggantikannya."
  },
